archive = pathlib.Path('/tmp/manabitan-original-jmdict-BA-46138650386-1c413.zip')
fields = ['termRecordValidationMs','termRecordFieldEncodeMs','termRecordEncodeMs','termRecordWriteMs','termRecordBuildMs']
rows = []
with zipfile.ZipFile(archive) as z:
    for row in expected:
        suffix = '/' + row['path'] + '/run-1.json'
        names = [n for n in z.namelist() if n.endswith(suffix)]
        assert len(names) == 1, suffix
        raw = z.read(names[0])
        assert hashlib.sha256(raw).hexdigest() == row['rawReportSha256']
        report = json.loads(raw)
        debugs = [p['data']['importDebug'] for p in report['phases'] if isinstance(p.get('data'),dict) and 'importDebug' in p['data']]
        assert len(debugs) == 1
        phases = [p for p in debugs[0]['importerPhaseTimings'] if 'termRecordValidationMs' in p.get('details',{})]
        assert len(phases) == 1
        phase = phases[0]
        rows.append({**row,'phase':phase['phase'],'values':{k:phase['details'][k] for k in fields}})
summary = []
for role in dict.fromkeys(r['role'] for r in rows):
    for arm in 'ABC':
        selected = [r for r in rows if r['role'] == role and r['arm'] == arm]
        if selected:
            summary.append({'role':role,'arm':arm,'count':len(selected),'mediansMs':{k:statistics.median(r['values'][k] for r in selected) for k in fields},'rangesMs':{k:[min(r['values'][k] for r in selected),max(r['values'][k] for r in selected)] for k in fields}})
result = {'schemaVersion':1,'scope':'Descriptive phase counters from all original JMdict BA reports; no new execution or observations, no change to closed whole-import decision','originalRun':46138650386,'baseline':'f28c2801fcfd9416f220b46b9cbafeee901c1cb2','product':'8982dd89fac525100bdcaca7507bfff7feb2c842','artifact':{'id':15261001868,'sha256':hashlib.sha256(archive.read_bytes()).hexdigest()},'limitations':['Phase counters can overlap or aggregate concurrent worker work; never add them to predict wall-clock savings','This is old frozen f28 source; no timing transfer to a300 or the unmeasured fusion prototype','One original host only; no claim of replication or qualification','All74 original raw reports are retained and SHA256 matched to the independent archive auditor'], 'rows':rows,'summary':summary}
out = pathlib.Path('/tmp/manabitan-original-jmdict-BA-phase-census-1c413.json')
out.write_text(json.dumps(result,indent=2)+'\n')
print(json.dumps({'path':str(out),'bytes':out.stat().st_size,'sha256':hashlib.sha256(out.read_bytes()).hexdigest(),'reports':len(rows),'summary':[s for s in summary if s['role']=='candidate']},indent=2))
